const items = $input.all();

// Separar detalle y resumen
const detalle = items.filter(i => i.json.tipo === 'detalle');
const resumen = items.find(i => i.json.tipo === 'resumen');

const filasHTML = detalle.map(d => `
    <tr>
        <td>#${d.json.venta_id}</td>
        <td>${d.json.cliente}</td>
        <td>${d.json.codigo}</td>
        <td>${d.json.producto}</td>
        <td>${d.json.cantidad}</td>
        <td>Q${parseFloat(d.json.precio_unitario).toFixed(2)}</td>
        <td>Q${parseFloat(d.json.subtotal).toFixed(2)}</td>
    </tr>
`).join('');

const telegramMsg = ` Resumen diario de ventas
${resumen ? resumen.json.fecha : ''}

Detalle:
${detalle.map(d =>
    `▪️ #${d.json.venta_id} | ${d.json.cliente}\n   ${d.json.producto} (x${d.json.cantidad}) | Q${parseFloat(d.json.subtotal).toFixed(2)}`
).join('\n')}

Resumen:
Total ventas: ${resumen ? resumen.json.venta_id : 0}
Total unidades: ${resumen ? resumen.json.cliente : 0}
Ingresos: Q${resumen ? parseFloat(resumen.json.subtotal).toFixed(2) : '0.00'}
Ticket promedio: Q${resumen ? parseFloat(resumen.json.precio_unitario).toFixed(2) : '0.00'}`;

return [{
    json: {
        filas_html: filasHTML,
        resumen: resumen ? resumen.json : {},
        telegram: telegramMsg
    }
}];
